#include "scarlett_cpu64.hpp"
#include <cassert>
#include <iostream>
using namespace genesis;
int main(){GuestMemory64 m;using F=GuestMemory64::Fault;assert(m.map(0x1000,4096,7)==F::none);Cpu64State init;init.gpr[1]=5;init.gpr[2]=0x1800;auto run=[&](auto code,unsigned steps=1){assert(m.write(0x1000,code)==F::none);return executeGuest64(m,0x1000,steps,0x1900,nullptr,0,0,0,0,&init);};auto s=run(std::array<uint8_t,3>{0xc1,0xe1,4});assert(s.gpr[1]==80&&s.steps==1);init.gpr[1]=0x80000000;s=run(std::array<uint8_t,2>{0xd1,0xf9});assert(s.gpr[1]==0xc0000000&&!s.of);init.gpr[1]=5;std::array<uint8_t,32> v{};for(unsigned i=0;i<32;++i)v[i]=i;assert(m.write(0x1858,v)==F::none);s=run(std::array<uint8_t,9>{0xc1,0xe1,4,0xc5,0xfe,0x6f,0x44,0x11,8},2);assert(s.steps==2&&s.xmm[0][15]==15&&s.ymmHigh[0][15]==31);ScarlettImports64 imp;assert(imp.install(m));auto addr=imp.registerImport("api-ms-win-crt-math-l1-1-0.dll","pow");assert(addr);init.gpr[0]=addr;double x=2,y=3;std::memcpy(init.xmm[0].data(),&x,8);std::memcpy(init.xmm[1].data(),&y,8);assert(m.write(0x1000,std::array<uint8_t,2>{0xff,0xd0})==F::none);s=executeGuest64(m,0x1000,1,0x1900,&imp,0,0,0,0,&init);std::memcpy(&x,s.xmm[0].data(),8);assert(s.steps==1&&x==8);std::cout<<"V31 tests passed\n";}
